import type { AssignmentStatus } from '~/client';
import type { BadgeVariants } from '~/components/ui/badge';

interface AssignmentStatusEntry {
  name: string;
  variant: BadgeVariants;
}

// Key order defines the user-visible filter/select order.
export const assignmentStatusConfig: Record<AssignmentStatus, AssignmentStatusEntry> = {
  training_required: { name: 'Training Required', variant: 'warning' },
  training_scheduled: { name: 'Training Scheduled', variant: 'info' },
  trained: { name: 'Trained', variant: 'info' },
  active: { name: 'Active', variant: 'success' },
  inactive: { name: 'Inactive', variant: 'default' },
  no_call_no_show: { name: 'No Call No Show', variant: 'destructive' },
  project_completed: { name: 'Project Completed', variant: 'default' },
};

const defaultAssignmentStatus: AssignmentStatusEntry = { name: '', variant: 'default' };

export function getAssignmentStatus(status: AssignmentStatus): AssignmentStatusEntry {
  return assignmentStatusConfig[status] ?? { ...defaultAssignmentStatus, name: snakeCaseToCapitalizedCase(status) };
}

export const assignmentStatusItems: SelectItem<AssignmentStatus>[] = Object.entries(assignmentStatusConfig).map(
  ([value, { name }]) => ({ value: value as AssignmentStatus, name })
);
